1	// SPDX-License-Identifier: MIT
2	pragma solidity ^0.8.0;
3	
4	import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
5	
6	contract SimpleDEX {
7	    IERC20 public arbiFake;
8	    IERC20 public dogeFake;
9	    address public owner;
10	    uint256 public rate; // 1 arbiFake = rate dogeFake
11	
12	    event Swap(address indexed user, address fromToken, address toToken, uint256 fromAmount, uint256 toAmount);
13	
14	    constructor(address _arbiFake, address _dogeFake, uint256 _rate) {
15	        require(_rate > 0, "Rate must be positive");
16	
17	        arbiFake = IERC20(_arbiFake);
18	        dogeFake = IERC20(_dogeFake);
19	        owner = msg.sender;
20	        rate = _rate;
21	    }
22	
23	    modifier onlyOwner() {
24	        require(msg.sender == owner, "Not owner");
25	        _;
26	    }
27	
28	    function setRate(uint256 _rate) external onlyOwner {
29	        // A zero rate would make swapArbiToDoge pay out 0 dogeFake while still
30	        // taking the user's arbiFake, since arbiAmount * 0 passes the balance
31	        // check with no revert (swapDogeToArbi is already protected since
32	        // dividing by zero reverts on its own).
33	        require(_rate > 0, "Rate must be positive");
